scenes.css:
#rf-root,.hf-root{--x3:#d8d1c5;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;animation:st-zoomout 0.5s cubic-bezier(.7,0,.84,0) 6s both;}.cam{position:absolute;inset:0;animation:st-cam 6.5s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.bd-grid{position:absolute;inset:0;background-image:linear-gradient(color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px),linear-gradient(90deg,color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px);background-size:108px 108px;background-position:-2px -2px}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}.ls-hd{position:absolute;left:90px;right:90px;top:230px}
.ls-pl{display:flex;align-items:center;gap:14px;font:500 34px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}
.ls-t{margin-top:26px;font-size:92px;font-weight:var(--rf-heading-weight);letter-spacing:-.04em;line-height:.98}
.plan{position:absolute;left:90px;right:90px;top:620px;height:600px;border-radius:36px;background:color-mix(in srgb,var(--rf-surface) 80%,transparent);border:2px solid color-mix(in srgb,var(--rf-text) 10%,transparent);padding:20px}
.plan svg{width:100%;height:100%}
.wl{fill:none;stroke:var(--rf-text);stroke-width:12;stroke-linecap:square;stroke-dasharray:1;stroke-dashoffset:1;animation:ld 1.68s cubic-bezier(.76,0,.24,1) both}
@keyframes ld{to{stroke-dashoffset:0}}
.rm{fill:color-mix(in srgb,var(--rf-accent) 22%,transparent);opacity:0;animation:k-fade .6s ease-out both}
.lb{position:absolute;font:600 28px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted);animation:k-fade .6s ease-out both}
.price{position:absolute;left:90px;top:1270px;font-size:130px;font-weight:600;letter-spacing:-.05em;transform-origin:left}
.specs{position:absolute;left:90px;right:90px;top:1440px;display:flex;gap:18px}
.sp{display:flex;align-items:center;gap:14px;font-size:36px;font-weight:600;padding:20px 28px;border-radius:22px;background:color-mix(in srgb,var(--rf-text) 8%,transparent)}
.sp .ic{color:var(--rf-muted)}

